package main

import (
    "fmt"
    "log"
    "net/http"
    "os"
    "time"
)

func main() {
    port := os.Getenv("PORT")
    if port == "" {
        port = "8080"
    }

    mux := http.NewServeMux()

    mux.HandleFunc("/", func(w http.ResponseWriter, r *http.Request) {
        w.WriteHeader(http.StatusOK)
        fmt.Fprintf(w, "Hello from the Terraform-managed Go app on Elastic Beanstalk! Time: %s\\n", time.Now().UTC().Format(time.RFC3339))
    })

    mux.HandleFunc("/health", func(w http.ResponseWriter, r *http.Request) {
        w.WriteHeader(http.StatusOK)
        fmt.Fprintln(w, "OK")
    })

    log.Printf("Go sample application listening on port %s", port)
    log.Fatal(http.ListenAndServe(":"+port, mux))
}

